/**
 * Host half of @local/grokbot-ui.
 *
 * Owns:
 *  - the local bot store (`data/bots.json`)
 *  - one live agent preset per bot (custom persona + full local coding tools)
 *  - the same-origin JSON API under `/grokbot/api/*` used by the browser UI
 *  - group-room replies, generated by the host's local model service
 *
 * Services are injected; a missing service fails the row loudly instead of
 * producing half-working routes. Service lookups in handlers are additionally
 * defensive so a transient failure becomes a friendly reply, never a crash.
 */
import path from 'node:path'
import { execFile } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { BotStore, HttpError, LIMITS, normalizeBotDraft, normalizeMessage, normalizeRoomDraft } from './store.js'
import { jsonResponse, postRoute } from './http.js'
import { transcribeAudio } from './transcribe.js'
import { mediaRoutes } from './media.js'
import { createLogger, slugify } from './util.js'
import { createPresetManager } from './presets.js'
import { buildBotSystemPrompt, buildRoomUserPrompt, cleanReply, mentionedBots, mentionsUser, selectTurnResponders } from './prompt.js'
import { ensureRoomSummary, ensureSummarizerBot } from './summary.js'
import { currentModelSelection, generateBotReply, REPLY_TIMEOUT_MS } from './llm.js'

/**
 * Hard bounds for one room turn: user message + bot replies + @mention
 * handoffs. Generous enough for a whole build/check/publish pipeline to run
 * autonomously after one user approval.
 */
const MAX_HANDOFF_ROUNDS = 8
const MAX_TURN_REPLIES = 16
/** Wall-clock budget for one whole room turn, so a ping chain cannot hang a room. */
const ROOM_TURN_TIMEOUT_MS = 300_000

/**
 * Services this row requires. All four are real Cordis services in the shipped
 * `web` profile. `logger` is deliberately NOT injected: cordis exposes it as a
 * context property rather than a provided service, and an `inject` entry for it
 * would leave this fiber INACTIVE forever (verified against cordis). The logger
 * is still read from the context defensively in `createLogger`.
 */
export const inject = ['webServer', 'llm', 'agentPresets', 'agentDefaultModel', 'credentials']

const here = path.dirname(fileURLToPath(import.meta.url))
const PKG_ROOT = path.resolve(here, '../..')
const DATA_DIR = path.join(PKG_ROOT, 'data')
const BOTS_FILE = path.join(DATA_DIR, 'bots.json')

/** Base order for bot presets in the preset picker. */
const PRESET_ORDER_BASE = 100

/**
 * Serialize async work per room so double-sends cannot interleave.
 * @param {{roomTails: Map<string, Promise<void>>}} runtime
 * @param {string} roomId
 * @param {() => Promise<T>} work
 * @returns {Promise<T>}
 * @template T
 */
function withRoomLock(runtime, roomId, work) {
  const previous = runtime.roomTails.get(roomId) ?? Promise.resolve()
  const run = previous.then(work)
  const guard = run.then(
    () => undefined,
    () => undefined,
  )
  runtime.roomTails.set(roomId, guard)
  guard.then(() => {
    if (runtime.roomTails.get(roomId) === guard) runtime.roomTails.delete(roomId)
  })
  return run
}

/**
 * Track one in-flight room send so deleting the room can abort it.
 * @param {{roomControllers: Map<string, Set<AbortController>>}} runtime
 * @param {string} roomId
 * @param {AbortController} controller
 */
function trackRoomController(runtime, roomId, controller) {
  let set = runtime.roomControllers.get(roomId)
  if (!set) {
    set = new Set()
    runtime.roomControllers.set(roomId, set)
  }
  set.add(controller)
}

/**
 * Stop tracking one room send and clear the entry when empty.
 * @param {{roomControllers: Map<string, Set<AbortController>>}} runtime
 * @param {string} roomId
 * @param {AbortController} controller
 */
function untrackRoomController(runtime, roomId, controller) {
  const set = runtime.roomControllers.get(roomId)
  if (!set) return
  set.delete(controller)
  if (set.size === 0) runtime.roomControllers.delete(roomId)
}

/**
 * Abort every in-flight reply for one room (used by room delete).
 * @param {{roomControllers: Map<string, Set<AbortController>>}} runtime
 * @param {string} roomId
 */
function abortRoom(runtime, roomId) {
  const set = runtime.roomControllers.get(roomId)
  if (!set) return
  for (const controller of set) {
    try {
      controller.abort()
    } catch {
      /* already aborted */
    }
  }
  runtime.roomControllers.delete(roomId)
}

/** POST /grokbot/api/bots — create when no id, update when the id exists. */
async function upsertBot(runtime, body) {
  const { store, presets, log } = runtime
  const draft = body?.bot
  if (draft === null || typeof draft !== 'object' || Array.isArray(draft)) {
    throw new HttpError(400, '`bot` is required and must be an object')
  }
  const requestedId = slugify(draft.id)
  const current = requestedId ? (store.findBot(requestedId) ?? null) : null
  if (requestedId && !current) {
    throw new HttpError(404, `bot "${requestedId}" was not found; create it without an id`)
  }
  const bot = normalizeBotDraft(draft, { existingBots: store.state.bots, current })
  store.upsertBot(bot)
  // Presets carry the current bot directory for cross-bot delegation, so a new
  // or edited bot refreshes every preset's allowlist.
  await presets.syncAll(store.state.bots)
  const failed = presets.status().failed.find((entry) => entry.id === `grokbot-${bot.id}`)
  const payload = { bots: store.snapshot().bots, bot }
  if (failed) payload.warning = `bot saved, but its agent preset failed: ${failed.error}`
  log.info(`[grokbot-ui] bot "${bot.id}" ${current ? 'updated' : 'created'} (preset ${failed ? 'failed' : 'ok'})`)
  return payload
}

/** POST /grokbot/api/bots/delete */
async function deleteBot(runtime, body) {
  const { store, presets, log } = runtime
  const id = slugify(body?.id)
  if (!id) throw new HttpError(400, '`id` is required')
  if (!store.deleteBot(id)) throw new HttpError(404, `bot "${id}" was not found`)
  await presets.syncAll(store.state.bots)
  log.info(`[grokbot-ui] bot "${id}" deleted`)
  return { bots: store.snapshot().bots }
}

/** POST /grokbot/api/rooms */
function createRoom(runtime, body) {
  const { store } = runtime
  const room = normalizeRoomDraft(body, { bots: store.state.bots })
  store.addRoom(room)
  return { rooms: store.snapshot().rooms, room }
}

/** POST /grokbot/api/rooms/delete */
function deleteRoom(runtime, body) {
  const { store } = runtime
  const id = typeof body?.id === 'string' ? body.id.trim() : ''
  if (!id) throw new HttpError(400, '`id` is required')
  if (!store.deleteRoom(id)) throw new HttpError(404, `room "${id}" was not found`)
  abortRoom(runtime, id)
  return { rooms: store.snapshot().rooms }
}

/** POST /grokbot/api/rooms/send — one serialized round of replies. */
function sendRoomMessage(runtime, body) {
  const { store } = runtime
  const roomId = typeof body?.roomId === 'string' ? body.roomId.trim() : ''
  if (!roomId) throw new HttpError(400, '`roomId` is required')
  const text = normalizeMessage({ role: 'user', text: body?.text }).text
  return withRoomLock(runtime, roomId, async () => {
    const room = store.findRoom(roomId)
    if (!room) throw new HttpError(404, `room "${roomId}" was not found`)

    /** @type {string[]|null} optional subset override of the room's bots */
    const requested = Array.isArray(body?.botIds)
      ? body.botIds.filter((value) => typeof value === 'string').map((value) => slugify(value))
      : null
    const available = room.botIds
      .filter((id) => !requested || requested.includes(id))
      .map((id) => store.findBot(id))
      .filter(Boolean)
    if (available.length === 0) throw new HttpError(400, 'this room has no available bots')

    // A bot that pinged `@user` paused the room; the user's next message resumes
    // exactly that handoff instead of requiring another explicit instruction.
    const pendingBefore = room.pending || null
    const responders = selectTurnResponders({ room, bots: available, text })
    if (pendingBefore) store.setRoomPending(roomId, null)
    // Fold older history into the shared brief before the new turn so every bot
    // starts from the brief + a short recent window instead of the full room.
    try {
      await ensureRoomSummary({ store, ctx: runtime.ctx, log: runtime.log, roomId, bots: available })
    } catch (error) {
      runtime.log.warn('[grokbot-ui] room brief update failed', error)
    }
    const userMessage = store.appendMessage(roomId, normalizeMessage({ role: 'user', text }))
    if (!userMessage) throw new HttpError(404, `room "${roomId}" was not found`)

    const controller = new AbortController()
    trackRoomController(runtime, roomId, controller)
    /** @type {object[]} */
    const replies = []
    // A bot can ping another bot by @Name in its reply; that bot then answers in
    // the next round. Both limits keep a ping-pong bounded in time and cost.
    let queue = responders
    let rounds = 0
    let paused = false
    const turnDeadline = Date.now() + ROOM_TURN_TIMEOUT_MS
    try {
      while (
        queue.length > 0 &&
        rounds < MAX_HANDOFF_ROUNDS &&
        replies.length < MAX_TURN_REPLIES &&
        Date.now() < turnDeadline
      ) {
        const nextQueue = []
        for (const bot of queue) {
          if (runtime.lifecycle.aborted) break
          if (replies.length >= MAX_TURN_REPLIES) break
          if (!store.findBot(bot.id)) continue // bot deleted while the room was answering
          const latest = store.findRoom(roomId)
          if (!latest) break
          const latestMessage = latest.transcript[latest.transcript.length - 1]
          const system = buildBotSystemPrompt(bot, latest, available)
          const prompt = buildRoomUserPrompt({
            bot,
            room: latest,
            bots: available,
            latest: latestMessage,
            resuming: Boolean(pendingBefore) && replies.length === 0,
          })
          let signal = controller.signal
          try {
            signal = AbortSignal.any([runtime.lifecycle.controller.signal, controller.signal, AbortSignal.timeout(REPLY_TIMEOUT_MS)])
          } catch {
            /* AbortSignal.any missing: fall back to the room controller only */
          }
          const result = await generateBotReply({
            ctx: runtime.ctx,
            log: runtime.log,
            bot,
            system,
            prompt,
            signal,
          })
          const replyText = cleanReply(result.text, LIMITS.reply) || '…'
          const reply = store.appendMessage(roomId, normalizeMessage({ role: 'bot', botId: bot.id, text: replyText }))
          if (!reply) break // room deleted mid-flight
          replies.push(reply)
          const handoffs = mentionedBots(replyText, available, bot.id)
          if (mentionsUser(replyText)) {
            // The bot asked the user (or is waiting for approval): stop the
            // autonomous chain and remember where it should resume.
            store.setRoomPending(roomId, {
              botId: bot.id,
              botIds: handoffs.map((candidate) => candidate.id),
              question: replyText,
              createdAt: Date.now(),
            })
            paused = true
            break
          }
          for (const mentioned of handoffs) {
            if (!nextQueue.some((candidate) => candidate.id === mentioned.id)) nextQueue.push(mentioned)
          }
        }
        if (paused) break
        queue = nextQueue
        rounds += 1
      }
    } finally {
      untrackRoomController(runtime, roomId, controller)
    }

    const finalRoom = store.findRoom(roomId)
    if (!finalRoom) throw new HttpError(409, 'the room was deleted while replies were being generated')
    return { room: finalRoom, replies }
  })
}

/**
 * Deliver one fixed-kind notification through the Omarchy desktop notifier.
 * All process arguments are passed separately (never through a shell).
 * @param {object} runtime
 * @param {object} body
 * @returns {Promise<{ok:boolean}>}
 */
function sendDesktopNotification(runtime, body) {
  const kind = body && body.kind
  const copy = {
    approval: ['Approval needed', 'is waiting for your approval.'],
    question: ['Agent has a question', 'is waiting for your answer.'],
    finished: ['Agent finished', 'finished its run.'],
  }[kind]
  if (!copy) throw new HttpError(400, 'unsupported notification kind')
  const rawName = typeof body.sessionName === 'string' ? body.sessionName : ''
  const sessionName = rawName.replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80) || 'An agent'
  const message = `${sessionName} ${copy[1]}`
  if (process.platform === 'darwin') {
    // Pass text as argv rather than interpolating it into AppleScript.
    const script = 'on run argv\n display notification (item 2 of argv) with title (item 1 of argv) sound name "default"\nend run'
    return new Promise((resolve) => {
      execFile('/usr/bin/osascript', ['-e', script, copy[0], message], { timeout: 5000 }, (error) => {
        if (error && !runtime.notificationFailureLogged) {
          runtime.notificationFailureLogged = true
          runtime.log.warn('[grokbot-ui] macOS notification could not be delivered', error)
        }
        resolve({ ok: !error, sound: !error })
      })
    })
  }
  const soundFile = kind === 'finished'
    ? '/usr/share/sounds/freedesktop/stereo/complete.oga'
    : '/usr/share/sounds/freedesktop/stereo/message-new-instant.oga'
  return new Promise((resolve) => {
    execFile('notify-send', ['--app-name=DeepSeek Harness', '--urgency=normal', '--expire-time=10000', copy[0], message], { timeout: 5000 }, (error) => {
      if (error) {
        if (!runtime.notificationFailureLogged) {
          runtime.notificationFailureLogged = true
          runtime.log.warn('[grokbot-ui] Omarchy desktop notification could not be delivered', error)
        }
        resolve({ ok: false, sound: false })
        return
      }
      execFile('paplay', ['--volume=13107', soundFile], { timeout: 5000 }, (soundError) => {
        if (soundError && !runtime.soundFailureLogged) {
          runtime.soundFailureLogged = true
          runtime.log.warn('[grokbot-ui] notification sound could not be played', soundError)
        }
        resolve({ ok: true, sound: !soundError })
      })
    })
  })
}

/**
 * Build the route table for one plugin instance.
 * @param {object} runtime
 * @returns {object[]}
 */
function buildRoutes(runtime) {
  const { ctx, log, store } = runtime
  return [
    {
      kind: 'exact',
      path: '/grokbot/api/state',
      resource: async () => {
        const snapshot = store.snapshot()
        return jsonResponse({
          version: snapshot.version,
          bots: snapshot.bots,
          rooms: snapshot.rooms,
          model: currentModelSelection(ctx),
        })
      },
    },
    {
      kind: 'exact',
      path: '/grokbot/api/health',
      resource: async () => {
        const snapshot = store.snapshot()
        return jsonResponse({
          ok: true,
          dataDir: DATA_DIR,
          bots: snapshot.bots.map((bot) => bot.id),
          rooms: snapshot.rooms.map((room) => room.id),
          presets: runtime.presets.status(),
          model: currentModelSelection(ctx),
        })
      },
    },
    {
      kind: 'exact',
      path: '/grokbot/api/bots',
      handler: postRoute((body) => upsertBot(runtime, body), log),
    },
    {
      kind: 'exact',
      path: '/grokbot/api/bots/delete',
      handler: postRoute((body) => deleteBot(runtime, body), log),
    },
    {
      kind: 'exact',
      path: '/grokbot/api/rooms',
      handler: postRoute((body) => createRoom(runtime, body), log),
    },
    {
      kind: 'exact',
      path: '/grokbot/api/rooms/delete',
      handler: postRoute((body) => deleteRoom(runtime, body), log),
    },
    {
      kind: 'exact',
      path: '/grokbot/api/rooms/send',
      handler: postRoute((body) => sendRoomMessage(runtime, body), log),
    },
    {
      kind: 'exact',
      path: '/grokbot/api/transcribe',
      handler: postRoute((body, req) => transcribeAudio(runtime.ctx, body, req), log),
    },
    ...mediaRoutes(),
    {
      kind: 'exact',
      path: '/grokbot/api/notify',
      handler: postRoute((body) => sendDesktopNotification(runtime, body), log),
    },
  ]
}

/**
 * Install the Grokbot host: store, presets, and HTTP API.
 * @param {any} ctx cordis context
 * @returns {Promise<void>}
 */
export async function apply(ctx) {
  const log = createLogger(ctx)
  const store = new BotStore(BOTS_FILE)
  store.load()


  const lifecycle = {
    aborted: false,
    controller: new AbortController(),
  }
  const runtime = {
    ctx,
    log,
    store,
    lifecycle,
    roomControllers: new Map(),
    roomTails: new Map(),
    presets: null,
  }
  runtime.presets = createPresetManager({ ctx, log, getBots: () => store.state.bots })

  const routes = buildRoutes(runtime)
  let disposed = false

  ctx.effect(() => {
    const disposers = []
    for (const route of routes) {
      try {
        disposers.push(ctx.webServer.register(route))
      } catch (error) {
        log.warn(`[grokbot-ui] could not register route ${route.path}`, error)
      }
    }
    return async () => {
      if (disposed) return
      disposed = true
      for (const dispose of disposers) {
        try {
          await dispose()
        } catch {
          /* route already gone */
        }
      }
      lifecycle.aborted = true
      try {
        lifecycle.controller.abort()
      } catch {
        /* ignore */
      }
      for (const roomId of [...runtime.roomControllers.keys()]) abortRoom(runtime, roomId)
      try {
        await runtime.presets.disposeAll()
      } catch (error) {
        log.warn('[grokbot-ui] failed to dispose agent presets', error)
      }
    }
  }, 'grokbot-ui.routes')

  log.info(`[grokbot-ui] host ready — ${store.state.bots.length} bot(s), ${store.state.rooms.length} room(s), data at ${BOTS_FILE}`)

  // Register one preset per stored bot. A broken bot only produces a warning
  // and a failed roster row; it never rejects plugin activation.
  try {
    await runtime.presets.syncAll(store.state.bots)
  } catch (error) {
    log.warn('[grokbot-ui] initial agent preset sync failed', error)
  }
}
